//! DSD tests: DSF/DFF demux, DSD to PCM decimation, `DoP`.
//!
//! Fixture provenance (see `tests/data/`):
//!
//! * The eight `dsf_dsd{64,128,256,512}_stereo.dsf` /
//!   `dff_dsd{64,128,256,512}_stereo.dff` files were generated by
//!   `/tmp/gen_dsd_fixtures.py` (kept outside the repo; the
//!   algorithm is re-implemented in Rust below for the
//!   in-memory variants). Each holds 0.1 s of stereo audio:
//!   left 1000 Hz sine, right 1500 Hz sine, amplitude 0.5,
//!   produced by a first-order sigma-delta modulator written
//!   for the fixtures. No real DSD recording was used, and no
//!   "looks like DSD" bytes were invented: every bit comes out
//!   of the modulator from the known sine.
//! * ffmpeg 8.1.2 has DSD *decoders* but no PCM-to-DSD encoder
//!   (`ffmpeg -encoders | grep -i dsd` returns nothing), so no
//!   reference encoder could have produced these files.
//! * Independent cross-check: ffmpeg 8.1.2 decodes the DFF
//!   fixtures to exactly 0.500 amplitude on both channels
//!   (measured 2026-11-08), which validates the modulator and
//!   the MSB-first packing. ffmpeg's DSF path does NOT decode
//!   these DSF files (it returns noise for both the
//!   spec-correct block layout and a byte-interleaved variant,
//!   and a DC test file decodes to toggling +/-1), so ffmpeg
//!   is not used as the DSF reference: the DSF layout is
//!   validated against the Sony DSF spec text (block size per
//!   channel 4096, LSB-first) and the sacd-ripper/PipeWire
//!   implementations instead.
//! * License: the fixtures are synthetic data generated for
//!   this project (no third-party audio), so there is no
//!   third-party license to record; they are covered by the
//!   workspace license like any other test vector.
//!
//! Quality numbers below are MEASURED by the tests (least-
//! squares sine fit / DFT / RMS), not asserted from the filter
//! design. Where a threshold appears, the measured value at
//! the time of writing is recorded in the comment next to it.

use std::io::Cursor;

use codec_whatttttttttttt_core::{
    dop_pcm_rate, pack_dop, reverse_bit_order, unpack_dop, Decoder, DsdDecimator, DsdDemuxer,
    DsdFormat, DsdHeader, DsdLevel, Frame, Packet,
};
use codec_whatttttttttttt_core::{Codec, Error};
use codec_whatttttttttttt_core::{DsdBlockLayout, DOP_MARKER_EVEN, DOP_MARKER_ODD};

const DATA: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/data");

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("{DATA}/{name}")).unwrap_or_else(|_| panic!("missing fixture {name}"))
}

/// First-order sigma-delta modulator, the same algorithm as
/// `/tmp/gen_dsd_fixtures.py`: integrator plus 1-bit quantiser.
/// Returns MSB-first bytes (bit 7 of each byte is earliest).
#[allow(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::cast_precision_loss,
    reason = "fixture counts stay far below 2^53 and rates/seconds are non-negative"
)]
fn sigma_delta_sine(freq_hz: f64, rate: u32, amplitude: f64, seconds: f64) -> Vec<u8> {
    let count = (f64::from(rate) * seconds) as usize;
    let mut state = 0.0f64;
    let mut out = Vec::with_capacity(count.div_ceil(8));
    let mut current: u8 = 0;
    let mut bits = 0;
    for i in 0..count {
        let x =
            amplitude * (2.0 * std::f64::consts::PI * freq_hz * i as f64 / f64::from(rate)).sin();
        state += x;
        let y = u8::from(state >= 0.0);
        state -= f64::from(2 * i32::from(y) - 1);
        current = (current << 1) | y;
        bits += 1;
        if bits == 8 {
            out.push(current);
            current = 0;
            bits = 0;
        }
    }
    if bits > 0 {
        out.push(current << (8 - bits));
    }
    out
}

/// Builds a minimal in-memory DSF file (stereo, 4096-byte
/// blocks, LSB-first) from per-channel MSB-first bitstreams.
fn build_dsf(rate: u32, left_msb: &[u8], right_msb: &[u8]) -> Vec<u8> {
    fn lsb_first(bytes: &[u8]) -> Vec<u8> {
        bytes.iter().map(|b| b.reverse_bits()).collect()
    }
    let left = lsb_first(left_msb);
    let right = lsb_first(right_msb);
    let sample_count = (left.len() * 8) as u64;
    let blocks = left.len().div_ceil(4096);
    let padded = blocks * 4096;
    let mut left_padded = left.clone();
    left_padded.resize(padded, 0);
    let mut right_padded = right.clone();
    right_padded.resize(padded, 0);
    // DSF data is block-interleaved: one block per channel in
    // turn ([L block][R block][L block][R block]...), NOT the
    // whole left channel followed by the whole right channel.
    let mut data = Vec::with_capacity(left_padded.len() + right_padded.len());
    for block in 0..blocks {
        data.extend_from_slice(&left_padded[block * 4096..(block + 1) * 4096]);
        data.extend_from_slice(&right_padded[block * 4096..(block + 1) * 4096]);
    }
    let total = 28 + 52 + 12 + data.len() as u64;
    let mut out = Vec::new();
    out.extend_from_slice(b"DSD ");
    out.extend_from_slice(&28u64.to_le_bytes());
    out.extend_from_slice(&total.to_le_bytes());
    out.extend_from_slice(&0u64.to_le_bytes());
    out.extend_from_slice(b"fmt ");
    out.extend_from_slice(&52u64.to_le_bytes());
    out.extend_from_slice(&1u32.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(&2u32.to_le_bytes());
    out.extend_from_slice(&2u32.to_le_bytes());
    out.extend_from_slice(&rate.to_le_bytes());
    out.extend_from_slice(&1u32.to_le_bytes());
    out.extend_from_slice(&sample_count.to_le_bytes());
    out.extend_from_slice(&4096u32.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes());
    out.extend_from_slice(b"data");
    out.extend_from_slice(&(12u64 + data.len() as u64).to_le_bytes());
    out.extend_from_slice(&data);
    out
}

/// Builds a minimal in-memory DFF file (stereo, byte-interleaved,
/// MSB-first) from per-channel MSB-first bitstreams.
fn build_dff(rate: u32, left_msb: &[u8], right_msb: &[u8]) -> Vec<u8> {
    fn chunk(id: [u8; 4], payload: &[u8]) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(&id);
        out.extend_from_slice(&(payload.len() as u64).to_be_bytes());
        out.extend_from_slice(payload);
        out
    }
    let mut data = Vec::with_capacity(left_msb.len() * 2);
    for (l, r) in left_msb.iter().zip(right_msb.iter()) {
        data.push(*l);
        data.push(*r);
    }
    let mut prop = b"SND ".to_vec();
    prop.extend_from_slice(&chunk(*b"FS  ", &rate.to_be_bytes()));
    let mut chnl = 2u16.to_be_bytes().to_vec();
    chnl.extend_from_slice(b"SLFT");
    chnl.extend_from_slice(b"SRGT");
    prop.extend_from_slice(&chunk(*b"CHNL", &chnl));
    prop.extend_from_slice(&chunk(*b"CMPR", b"DSD "));
    let body = [
        chunk(*b"FVER", &0x0105_0000u32.to_be_bytes()),
        chunk(*b"PROP", &prop),
        chunk(*b"DSD ", &data),
    ]
    .concat();
    let mut out = b"FRM8".to_vec();
    out.extend_from_slice(&(4u64 + body.len() as u64).to_be_bytes());
    out.extend_from_slice(b"DSD ");
    out.extend_from_slice(&body);
    out
}

/// Least-squares fit of a sine at `freq_hz` over whole periods
/// of `samples` (one channel, deinterleaved by the caller).
/// Returns the amplitude. Robust to uncorrelated noise, unlike
/// a single DFT bin when the frequency is not bin-centred.
#[allow(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::cast_precision_loss,
    reason = "test sample counts stay far below 2^53 and are non-negative"
)]
fn sine_amplitude(samples: &[f32], sample_rate: f64, freq_hz: f64) -> f64 {
    let period = sample_rate / freq_hz;
    let periods = (samples.len() as f64 / period).floor() as usize;
    if periods == 0 {
        return 0.0;
    }
    let n = (periods as f64 * period) as usize;
    let mut s = 0.0f64;
    let mut c = 0.0f64;
    for (i, &v) in samples.iter().take(n).enumerate() {
        let phase = 2.0 * std::f64::consts::PI * freq_hz * i as f64 / sample_rate;
        s += f64::from(v) * phase.sin();
        c += f64::from(v) * phase.cos();
    }
    (s * s + c * c).sqrt() * 2.0 / n as f64
}

/// RMS of one channel's samples.
#[allow(
    clippy::cast_precision_loss,
    reason = "test sample counts stay far below 2^53"
)]
fn rms(samples: &[f32]) -> f64 {
    if samples.is_empty() {
        return 0.0;
    }
    (samples
        .iter()
        .map(|&v| f64::from(v) * f64::from(v))
        .sum::<f64>()
        / samples.len() as f64)
        .sqrt()
}

/// Deinterleaves one channel out of interleaved samples.
fn channel(samples: &[f32], channels: usize, wanted: usize) -> Vec<f32> {
    samples
        .iter()
        .skip(wanted)
        .step_by(channels)
        .copied()
        .collect()
}

/// Decodes a whole fixture file to PCM at `target_rate` and
/// returns the interleaved samples plus the header.
fn decode_fixture(name: &str, target_rate: u32) -> (DsdHeader, Vec<f32>) {
    let bytes = fixture(name);
    let mut demuxer = DsdDemuxer::new(Cursor::new(bytes)).unwrap();
    let header = demuxer.header().clone();
    let mut decoder = Decoder::from_dsd_header(&header)
        .unwrap()
        .with_dsd_output_rate(target_rate)
        .unwrap();
    let mut samples = Vec::new();
    while let Some(packet) = demuxer.next_packet().unwrap() {
        match decoder.decode(&packet).unwrap() {
            Frame::Audio(audio) => samples.extend_from_slice(&audio.samples),
            Frame::Video(_) => panic!("expected audio"),
        }
    }
    if let Some(Frame::Audio(tail)) = decoder.flush().unwrap() {
        samples.extend_from_slice(&tail.samples);
    }
    (header, samples)
}

/// All packets of a fixture, decoded through the decimator
/// directly (bypassing `Decoder`), at `target_rate`.
fn decimate_fixture(name: &str, target_rate: u32) -> (DsdHeader, Vec<f32>) {
    let bytes = fixture(name);
    let mut demuxer = DsdDemuxer::new(Cursor::new(bytes)).unwrap();
    let header = demuxer.header().clone();
    let mut decimator = DsdDecimator::new(
        header.sample_rate,
        header.channels,
        target_rate,
        header.layout(),
    )
    .unwrap();
    let mut samples = Vec::new();
    while let Some(packet) = demuxer.next_packet().unwrap() {
        samples.extend(decimator.feed(&packet.data).unwrap());
    }
    samples.extend(decimator.flush().unwrap());
    (header, samples)
}

// ---------------------------------------------------------------- headers

#[test]
fn dsf_header_parses_all_four_levels() {
    for (name, rate, level) in [
        ("dsf_dsd64_stereo.dsf", 2_822_400u32, DsdLevel::Dsd64),
        ("dsf_dsd128_stereo.dsf", 5_644_800, DsdLevel::Dsd128),
        ("dsf_dsd256_stereo.dsf", 11_289_600, DsdLevel::Dsd256),
        ("dsf_dsd512_stereo.dsf", 22_579_200, DsdLevel::Dsd512),
    ] {
        let demuxer = DsdDemuxer::new(Cursor::new(fixture(name))).unwrap();
        let header = demuxer.header();
        assert_eq!(header.format, DsdFormat::Dsf);
        assert_eq!(header.sample_rate, rate);
        assert_eq!(header.level, level);
        assert_eq!(header.channels, 2);
        assert_eq!(header.block_size_per_channel, 4096);
        assert_eq!(header.sample_count, u64::from(rate) / 10);
        assert_eq!(header.data_offset, 92);
    }
}

#[test]
fn dff_header_parses_all_four_levels() {
    for (name, rate, level) in [
        ("dff_dsd64_stereo.dff", 2_822_400u32, DsdLevel::Dsd64),
        ("dff_dsd128_stereo.dff", 5_644_800, DsdLevel::Dsd128),
        ("dff_dsd256_stereo.dff", 11_289_600, DsdLevel::Dsd256),
        ("dff_dsd512_stereo.dff", 22_579_200, DsdLevel::Dsd512),
    ] {
        let demuxer = DsdDemuxer::new(Cursor::new(fixture(name))).unwrap();
        let header = demuxer.header();
        assert_eq!(header.format, DsdFormat::Dff);
        assert_eq!(header.sample_rate, rate);
        assert_eq!(header.level, level);
        assert_eq!(header.channels, 2);
        assert!(header.data_offset > 0);
        assert!(header.data_size > 0);
    }
}

#[test]
fn dsd512_stereo_bytes_per_second_is_5_644_800() {
    let demuxer = DsdDemuxer::new(Cursor::new(fixture("dsf_dsd512_stereo.dsf"))).unwrap();
    assert_eq!(demuxer.header().bytes_per_second(), 5_644_800);
    assert!((demuxer.header().duration_seconds() - 0.1).abs() < 1e-9);
}

#[test]
fn demuxer_returns_block_packets_with_rising_timestamps() {
    let mut demuxer = DsdDemuxer::new(Cursor::new(fixture("dsf_dsd64_stereo.dsf"))).unwrap();
    let mut count = 0;
    let mut previous = 0u64;
    while let Some(packet) = demuxer.next_packet().unwrap() {
        assert_eq!(packet.codec, Codec::Dsd);
        // One DSF block group: 4096 bytes per channel, stereo.
        assert_eq!(packet.data.len(), 8192);
        assert!(packet.timestamp >= previous);
        previous = packet.timestamp;
        count += 1;
    }
    assert_eq!(count, 9);
}

#[test]
fn dff_demuxer_returns_4096_byte_channel_packets() {
    let mut demuxer = DsdDemuxer::new(Cursor::new(fixture("dff_dsd64_stereo.dff"))).unwrap();
    let mut count = 0;
    let mut last_len = 0;
    while let Some(packet) = demuxer.next_packet().unwrap() {
        // Full packets hold 4096 bytes per channel; the last
        // packet holds the remainder (DFF has no block padding).
        assert!(packet.data.len() <= 8192);
        last_len = packet.data.len();
        count += 1;
    }
    assert_eq!(count, 9);
    assert_eq!(last_len, 70560 - 8 * 8192);
}

