#[test]
fn truncated_dsf_header_is_rejected() {
    let mut bytes = fixture("dsf_dsd64_stereo.dsf");
    bytes.truncate(40);
    let err = DsdDemuxer::new(Cursor::new(bytes)).unwrap_err();
    assert!(matches!(err, Error::Truncated { .. }));
}

#[test]
fn dsf_declared_data_size_larger_than_file_is_rejected() {
    let mut bytes = fixture("dsf_dsd64_stereo.dsf");
    // Inflate the declared data chunk size (offset 84, u64 LE).
    let huge = 12u64 + 10_000_000;
    bytes[84..92].copy_from_slice(&huge.to_le_bytes());
    // The header still parses (declared samples fit), but
    // reading past the real end of the file fails: the first
    // packets succeed, a later one runs past the end.
    let mut demuxer = DsdDemuxer::new(Cursor::new(bytes)).unwrap();
    let err = loop {
        match demuxer.next_packet() {
            Ok(Some(_)) => {}
            Ok(None) => panic!("expected a truncated read, got end of stream"),
            Err(err) => break err,
        }
    };
    assert!(matches!(err, Error::Truncated { .. }));
}

#[test]
fn dsf_nine_channels_is_rejected() {
    let left = sigma_delta_sine(1000.0, 2_822_400, 0.5, 0.01);
    let right = sigma_delta_sine(1500.0, 2_822_400, 0.5, 0.01);
    let mut bytes = build_dsf(2_822_400, &left, &right);
    bytes[52..56].copy_from_slice(&9u32.to_le_bytes());
    let err = DsdDemuxer::new(Cursor::new(bytes)).unwrap_err();
    assert!(matches!(err, Error::InvalidData { .. }));
}

