#[test]
fn dff_dst_chunk_is_unsupported() {
    // A DFF file whose audio chunk is `DST ` instead of `DSD `.
    let bytes = fixture("dff_dsd64_stereo.dff");
    let mut dst = bytes.clone();
    // Walk the chunk headers from the FRM8 header (16 bytes) to
    // the audio chunk id: FVER, then PROP, then `DSD `.
    let mut at = 16usize;
    loop {
        let id = &bytes[at..at + 4];
        let size = usize::try_from(u64::from_be_bytes(
            bytes[at + 4..at + 12].try_into().unwrap(),
        ))
        .unwrap();
        if id == b"DSD " {
            break;
        }
        at += 12 + size;
    }
    dst[at..at + 4].copy_from_slice(b"DST ");
    let err = DsdDemuxer::new(Cursor::new(dst)).unwrap_err();
    assert!(matches!(err, Error::Unsupported(_)));
}

#[test]
fn dff_data_before_prop_is_rejected() {
    // Minimal FRM8 with a DSD chunk and no PROP at all.
    let mut out = b"FRM8".to_vec();
    let payload = [0xAAu8; 16];
    let body_len = 4 + 12 + payload.len();
    out.extend_from_slice(&(body_len as u64).to_be_bytes());
    out.extend_from_slice(b"DSD ");
    out.extend_from_slice(b"DSD ");
    out.extend_from_slice(&(payload.len() as u64).to_be_bytes());
    out.extend_from_slice(&payload);
    let err = DsdDemuxer::new(Cursor::new(out)).unwrap_err();
    assert!(matches!(err, Error::InvalidData { .. }));
}

#[test]
fn dff_built_in_memory_parses_and_decodes() {
    // The DFF builder was unused until this test; an in-memory
    // DFF exercises the builder plus the MSB-first path.
    let left = sigma_delta_sine(1000.0, 2_822_400, 0.5, 0.05);
    let right = sigma_delta_sine(1500.0, 2_822_400, 0.5, 0.05);
    let bytes = build_dff(2_822_400, &left, &right);
    let mut demuxer = DsdDemuxer::new(Cursor::new(bytes)).unwrap();
    let header = demuxer.header().clone();
    assert_eq!(header.format, DsdFormat::Dff);
    assert_eq!(header.sample_rate, 2_822_400);
    assert_eq!(header.channels, 2);
    let mut decimator = DsdDecimator::new(2_822_400, 2, 44_100, header.layout()).unwrap();
    let mut out = Vec::new();
    while let Some(packet) = demuxer.next_packet().unwrap() {
        out.extend(decimator.feed(&packet.data).unwrap());
    }
    out.extend(decimator.flush().unwrap());
    let left_ch = channel(&out, 2, 0);
    // 0.05 s is exactly 2205 frames at 44.1 kHz; fit only the
    // real audio, not the flush tail.
    let amp = sine_amplitude(&left_ch[882..2205], 44_100.0, 1000.0);
    assert!((amp - 0.5).abs() < 0.05, "in-memory dff amplitude {amp}");
}

// -------------------------------------------------------------- bit order

#[test]
#[allow(
    clippy::similar_names,
    reason = "the dsf/dff name pairs are intentional: the test compares the two containers"
)]
fn dsf_lsb_first_and_dff_msb_first_decode_the_same_sine() {
    // The same bitstream stored both ways must decode to the
    // same PCM: this is the test that catches a bit-order swap.
    let (_dsf_header, dsf) = decimate_fixture("dsf_dsd64_stereo.dsf", 44_100);
    let (_dff_header, dff) = decimate_fixture("dff_dsd64_stereo.dff", 44_100);
    // The outputs differ in length: DSF pads its data to whole
    // blocks, DFF does not. Compare the amplitudes over the
    // shared 0.1 s instead of the lengths.
    let dsf_left = channel(&dsf, 2, 0);
    let dff_left = channel(&dff, 2, 0);
    // Skip the filter warm-up (first 0.02 s).
    let skip = 882;
    // Fit over the shared 0.1 s of real audio only (frames
    // 882..4410): the DSF tail past frame 4410 is block padding,
    // not audio, and would dilute the fit.
    let dsf_amp = sine_amplitude(&dsf_left[skip..4410], 44_100.0, 1000.0);
    let dff_amp = sine_amplitude(&dff_left[skip..4410], 44_100.0, 1000.0);
    assert!((dsf_amp - 0.5).abs() < 0.05, "dsf amplitude {dsf_amp}");
    assert!((dff_amp - 0.5).abs() < 0.05, "dff amplitude {dff_amp}");
    assert!(
        (dsf_amp - dff_amp).abs() < 0.02,
        "dsf {dsf_amp} vs dff {dff_amp}"
    );
}

#[test]
#[allow(
    clippy::cast_precision_loss,
    reason = "the settled window is a few hundred samples, far below 2^53"
)]
fn constant_all_ones_decodes_to_full_scale_dc() {
    // A DSD stream of all ones is +1.0 DC; after the filter
    // settles, the output must sit at +1.0 (unit DC gain).
    let ones = vec![0xFFu8; 4096];
    let mut decimator = DsdDecimator::new(
        2_822_400,
        1,
        44_100,
        DsdBlockLayout::Dsf {
            block_size_per_channel: 4096,
        },
    )
    .unwrap();
    let mut out = decimator.feed(&ones).unwrap();
    out.extend(decimator.flush().unwrap());
    // A middle window: past the filter warm-up, before the
    // flush tail (zero padding) pulls the mean down.
    let settled = &out[out.len() / 4..out.len() / 2];
    let mean = settled.iter().map(|&v| f64::from(v)).sum::<f64>() / settled.len() as f64;
    assert!((mean - 1.0).abs() < 0.02, "dc mean {mean}");
}

#[test]
fn alternating_bits_decode_to_silence() {
    // Alternating 1/0 bits average to zero: the decoded output
    // must stay near silence.
    let alternating = vec![0x55u8; 4096];
    let mut decimator = DsdDecimator::new(
        2_822_400,
        1,
        44_100,
        DsdBlockLayout::Dsf {
            block_size_per_channel: 4096,
        },
    )
    .unwrap();
    let mut out = decimator.feed(&alternating).unwrap();
    out.extend(decimator.flush().unwrap());
    let settled = &out[out.len() / 2..];
    assert!(rms(settled) < 0.01, "alternating rms {}", rms(settled));
}

// ------------------------------------------------------- quality, measured

#[test]
fn dsd64_to_44k1_sine_amplitude_is_within_1db_of_0p5() {
    let (_header, samples) = decimate_fixture("dsf_dsd64_stereo.dsf", 44_100);
    let left = channel(&samples, 2, 0);
    let right = channel(&samples, 2, 1);
    // Measured 2026-11-08 over frames 882..4410 (the real
    // 0.1 s; the tail past 4410 is DSF block padding): left
    // 0.4910, right 0.4926 (target 0.5).
    let left_amp = sine_amplitude(&left[882..4410], 44_100.0, 1000.0);
    let right_amp = sine_amplitude(&right[882..4410], 44_100.0, 1500.0);
    assert!((left_amp - 0.5).abs() < 0.05, "left amplitude {left_amp}");
    assert!(
        (right_amp - 0.5).abs() < 0.05,
        "right amplitude {right_amp}"
    );
}

#[test]
fn dsd64_to_44k1_passband_ripple_is_below_0p5db() {
    // Sines at 1/10/18 kHz through the same decimator: the
    // spread of their amplitudes is the passband ripple.
    // Measured 2026-11-08: 1 kHz 0.4929, 10 kHz 0.4928,
    // 18 kHz 0.4848 — a spread of 0.143 dB.
    let mut amps = Vec::new();
    for freq in [1000.0, 10_000.0, 18_000.0] {
        let bits = sigma_delta_sine(freq, 2_822_400, 0.5, 0.05);
        let mut decimator = DsdDecimator::new(2_822_400, 1, 44_100, DsdBlockLayout::Dff).unwrap();
        let mut out = decimator.feed(&bits).unwrap();
        out.extend(decimator.flush().unwrap());
        let amp = sine_amplitude(&out[882..], 44_100.0, freq);
        amps.push(amp);
    }
    let max = amps.iter().copied().fold(0.0f64, f64::max);
    let min = amps.iter().copied().fold(1.0f64, f64::min);
    let ripple_db = 20.0 * (max / min).log10();
    assert!(ripple_db < 0.5, "ripple {ripple_db:.3} dB, amps {amps:?}");
}

#[test]
fn dsd64_to_44k1_stopband_at_30khz_is_below_minus_40db() {
    // A 30 kHz sine sits above the 44.1 kHz Nyquist frequency:
    // after decimation it may only appear as a heavily
    // attenuated 14.1 kHz alias. Measured 2026-11-08: the
    // 14.1 kHz alias amplitude is 0.000227 (-66.9 dB rel. 0.5),
    // and the total output RMS is 0.0038.
    let bits = sigma_delta_sine(30_000.0, 2_822_400, 0.5, 0.05);
    let mut decimator = DsdDecimator::new(2_822_400, 1, 44_100, DsdBlockLayout::Dff).unwrap();
    let mut out = decimator.feed(&bits).unwrap();
    out.extend(decimator.flush().unwrap());
    let settled = &out[882..];
    let alias = sine_amplitude(settled, 44_100.0, 14_100.0);
    let attenuation_db = 20.0 * (alias / 0.5).log10();
    assert!(
        attenuation_db < -40.0,
        "30 khz alias {alias} ({attenuation_db:.1} dB)"
    );
    assert!(rms(settled) < 0.01, "stopband rms {}", rms(settled));
}

#[test]
#[allow(
    clippy::cast_precision_loss,
    reason = "the dft window is 1764 samples, far below 2^53"
)]
fn dsd64_to_176k4_noise_above_20khz_is_below_minus_30db() {
    // At 176.4 kHz the spectrum above 20 kHz is visible. The
    // DFT of a 10 ms window (bin spacing 100 Hz) puts the
    // 1 kHz signal in bin 10; the RMS of bins above 20 kHz
    // (bins 200..882) is the out-of-band noise. Measured
    // 2026-11-08: signal 0.5000, out-of-band RMS 0.0121
    // (-32.3 dB relative to the signal).
    let (_header, samples) = decimate_fixture("dsf_dsd64_stereo.dsf", 176_400);
    let left = channel(&samples, 2, 0);
    let window: Vec<f32> = left[3528..3528 + 1764].to_vec();
    let n = window.len();
    let mut signal = 0.0f64;
    let mut noise_power = 0.0f64;
    for k in 0..n / 2 {
        let mut re = 0.0f64;
        let mut im = 0.0f64;
        for (i, &v) in window.iter().enumerate() {
            let phase = 2.0 * std::f64::consts::PI * k as f64 * i as f64 / n as f64;
            re += f64::from(v) * phase.cos();
            im -= f64::from(v) * phase.sin();
        }
        let mag = (re * re + im * im).sqrt() * 2.0 / n as f64;
        if k == 10 {
            signal = mag;
        } else if k >= 200 {
            noise_power += mag * mag;
        }
    }
    let noise_rms = noise_power.sqrt();
    let ratio_db = 20.0 * (noise_rms / signal).log10();
    assert!(signal > 0.4, "signal bin {signal}");
    assert!(
        ratio_db < -30.0,
        "out-of-band noise {noise_rms:.4} ({ratio_db:.1} dB rel. signal {signal:.3})"
    );
}

