// ------------------------------------------------------------------- dop

#[test]
fn dop_markers_are_0x05_then_0xfa() {
    assert_eq!(DOP_MARKER_EVEN, 0x05);
    assert_eq!(DOP_MARKER_ODD, 0xFA);
    assert_eq!(dop_pcm_rate(2_822_400), Some(176_400));
    assert_eq!(dop_pcm_rate(5_644_800), Some(352_800));
    assert_eq!(dop_pcm_rate(11_289_600), None);
    assert_eq!(dop_pcm_rate(22_579_200), None);
}

#[test]
fn dop_round_trip_dsd64_and_dsd128_are_exact() {
    for rate in [2_822_400u32, 5_644_800] {
        let left = sigma_delta_sine(1000.0, rate, 0.5, 0.01);
        let right = sigma_delta_sine(1500.0, rate, 0.5, 0.01);
        let packed = pack_dop(&[&left, &right], rate).unwrap();
        assert_eq!(packed.len(), left.len() / 2 * 2 * 3);
        let unpacked = unpack_dop(&packed, 2, rate).unwrap();
        assert_eq!(unpacked[0], left);
        assert_eq!(unpacked[1], right);
    }
}

#[test]
fn dop_pack_of_dsf_bytes_needs_bit_reversal_first() {
    // DSF bytes are LSB-first; DoP is MSB-first. Packing raw DSF
    // bytes without reversing them, then unpacking, must give
    // the bit-reversed stream back — the reversal is the
    // caller's job, and this test pins the direction.
    let msb = sigma_delta_sine(1000.0, 2_822_400, 0.5, 0.01);
    let lsb = reverse_bit_order(&msb);
    let packed = pack_dop(&[&lsb], 2_822_400).unwrap();
    let unpacked = unpack_dop(&packed, 1, 2_822_400).unwrap();
    assert_eq!(unpacked[0], lsb);
    assert_eq!(reverse_bit_order(&unpacked[0]), msb);
}

#[test]
fn dop_bad_marker_is_rejected() {
    let left = sigma_delta_sine(1000.0, 2_822_400, 0.5, 0.01);
    let mut packed = pack_dop(&[&left], 2_822_400).unwrap();
    packed[2] = 0x00;
    let err = unpack_dop(&packed, 1, 2_822_400).unwrap_err();
    assert!(matches!(err, Error::InvalidData { .. }));
}

#[test]
fn dop_dsd256_and_dsd512_are_unsupported() {
    let left = sigma_delta_sine(1000.0, 11_289_600, 0.5, 0.01);
    let err = pack_dop(&[&left], 11_289_600).unwrap_err();
    assert!(matches!(err, Error::Unsupported(_)));
    let err = unpack_dop(&[0u8; 6], 1, 22_579_200).unwrap_err();
    assert!(matches!(err, Error::Unsupported(_)));
}
